// Render only text and server-owned source links; model output never becomes HTML.
export const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escapeHTML;
const safeURL=value=>String(value).startsWith('https://') ? e(value) : '#';
export async function requestAnalysis(profile, code, signal) {
  const {scenario, ...fields}=profile;
  const headers={'Content-Type':'application/json','X-Demo-Code':code};
  const response=await fetch('/api/analyses',{method:'POST',headers,body:JSON.stringify({...fields,hours:Number(fields.hours)}),signal});
  let data=await response.json().catch(()=>({detail:'The server returned an unreadable response.'}));
  if(!response.ok) throw new Error(typeof data.detail==='string'?data.detail:'Analysis failed. Check your answers and try again.');
  if(data.job_id){
    const jobId=data.job_id;
    for(let attempt=0;attempt<160;attempt++){
      await new Promise((resolve,reject)=>{const timer=setTimeout(resolve,3000);signal?.addEventListener('abort',()=>{clearTimeout(timer);reject(new DOMException('Aborted','AbortError'));},{once:true});});
      const poll=await fetch(`/api/analyses/${encodeURIComponent(jobId)}`,{headers,signal});
      const status=await poll.json();
      if(!poll.ok||status.status==='error') throw new Error(status.detail||'Analysis is unavailable. Please retry.');
      if(status.status==='complete'){data=status.result;break;}
    }
  }
  if(data.mode!=='real-ai' || !data.analysis || !data.inference?.request_id) throw new Error('The response did not identify real inference. No report was displayed.');
  return data;
}

export async function requestMatching(profile) {
  const {scenario,...fields}=profile;
  const response=await fetch('/api/match',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...fields,hours:Number(fields.hours)})});
  const data=await response.json();
  if(!response.ok) throw new Error(data.detail||'Source matching unavailable.');
  if(data.mode!=='source-matching') throw new Error('Unexpected matching response.');
  return data;
}

export function renderMatching(result) {
 const s=result.evidence.sources;
 return `<span class="demo-badge">SOURCE-BASED MATCHING · NO AI INFERENCE</span><p>${e(result.note)}</p><p>Score = skill overlap (0–70) + task-word overlap (0–20) + published growth category (0–10). This is a limited English heuristic, not a hiring or replacement probability. Unmentioned skills are not proven gaps.</p><div class="ranking">${result.ranking.map((r,i)=>`<article><span>#${i+1}</span><div><strong>${e(r.title)}</strong><p>${e(r.growth)} · ${e(r.period)} · US data</p><small>Skills ${r.components.skill_overlap}/70 · Task context ${r.components.task_context}/20 · Trend ${r.components.published_trend}/10</small><p>Skills mentioned: ${e(r.matched_skills.join(', ')||'No literal matches')}</p><p>Not mentioned: ${e(r.gaps.join(', '))}</p><p>Context words: ${e(r.overlap_terms.join(', ')||'None')}</p>${references([r.source_id],s)}<p>Proposed SDG ${e(r.sdg.target)} connection: ${e(r.sdg.rationale)}</p><a href="https://sdgs.un.org/goals/goal8" target="_blank" rel="noopener noreferrer">UN target 8.2</a><p>Each listed skill: SDG 4.4 through employment-related learning; validate it with a practical work sample. This is an editorial mapping, not measured impact.</p><a href="https://sdgs.un.org/goals/goal4" target="_blank" rel="noopener noreferrer">UN target 4.4</a></div><b>${r.score}<small>/100</small></b></article>`).join('')}</div><p>${e(result.evidence.attribution)} <a href="https://creativecommons.org/licenses/by/4.0/">CC BY 4.0</a>.</p><p>Snapshot ${e(result.evidence.version)} · retrieved ${e(result.evidence.retrieved_at)}. ${e(result.evidence.geography)}</p>`;
}

function references(ids,sources) {
  return `<span class="source-links">${ids.map(id=>{const s=sources[id];return s?`<a href="${safeURL(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.title)}</a>`:'';}).join(' · ')}</span>`;
}
function claim(c,sources) {return `<p>${e(c.text)}</p>${references(c.source_ids,sources)}`;}
function sdg(value) {return `<details class="sdg"><summary>SDG ${e(value.target)} · proposed contribution</summary><p>${e(value.rationale)}</p><p><strong>Check:</strong> ${e(value.measure)}</p><a href="https://sdgs.un.org/goals/goal${value.target.startsWith('4')?'4':'8'}" target="_blank" rel="noopener noreferrer">UN target definition</a></details>`;}
const headings={capability:['CAPABILITY ASSESSMENT','Your experience, in context.'],impact:['FUTURE SKILLS RADAR','What is changing — and what is uncertain.'],paths:['CAREER PATHS','Compare analyzed paths with source-based candidates.'],plan:['30-DAY ACTION PLAN','Turn an idea into evidence.']};

export function renderLiveReport(r,page,pathId) {
 const a=r.analysis,s=r.evidence.sources;
 const head=`<div class="report-head"><span class="kicker">${headings[page][0]}</span><h1>${headings[page][1]}</h1><p>Real model output · ${e(r.inference.model)} · ${e(r.generated_at.slice(0,10))}</p><span class="demo-badge">AI INFERENCE · SYNTHETIC PROFILE</span></div>`;
 let body='';
 if(page==='capability') body=`<div class="profile-summary">${claim(a.summary,s)}</div><div class="capability-grid">${a.capabilities.map((c,i)=>`<article class="cap-card cap-${i}"><span class="small-label">${e(c.lens)}</span><h2>${{independent:'Independent professional capability',collaboration:'AI collaboration capability',extended:'AI-extended capability'}[c.lens]}</h2>${claim(c.assessment,s)}<div class="cap-detail"><span>FICTIONAL SELF-REPORT, NOT VERIFIED EVIDENCE</span><p>“${e(c.evidence_quote)}”</p></div><div class="cap-next"><span>WHAT TO VERIFY</span>${claim(c.verify_next,s)}</div></article>`).join('')}</div>`;
 if(page==='impact') body=`${sourceRadar(r.evidence)}<h2 class="section-space">Skill signals</h2><p>Conditional AI assessments. Research signals and US employment projections do not prove a skill is rising in Malaysia.</p><div class="task-grid">${a.radar.map(t=>`<article class="task-card"><span class="kicker">${e(t.direction)}</span><h2>${e(t.skill)}</h2>${claim(t.reasoning,s)}${sdg(t.sdg)}</article>`).join('')}</div><h2 class="section-space">Your specific tasks</h2><div class="task-grid">${a.tasks.map(t=>`<article class="task-card"><span class="kicker">${e(t.category)} · MODEL ASSESSMENT</span><h2>${e(t.input_quote)}</h2>${claim(t.assessment,s)}<strong>Human review</strong>${claim(t.human_check,s)}</article>`).join('')}</div><h2 class="section-space">Two futures to prepare for</h2><div class="paths-grid">${a.scenarios.map(x=>`<article class="path-card"><h2>${e(x.pace)} AI adoption</h2><p><strong>Assumption:</strong> ${e(x.assumption)}</p>${claim(x.implication,s)}<strong>Watch for</strong>${claim(x.watch_for,s)}</article>`).join('')}</div>`;
 if(page==='paths') {
  const analyzedRoleIds=new Set(a.paths.map(p=>p.role_id));
  const candidate=r.ranking.find(role=>!analyzedRoleIds.has(role.id));
  const candidateCard=candidate?`<article class="path-card source-candidate ${pathId==='C'?'selected':''}"><div class="path-top"><span>PATH C · SOURCE MATCH</span>${pathId==='C'?'<span class="selected-pill">SELECTED</span>':''}</div><h2>${e(candidate.title)}</h2><p class="path-subtitle">Additional occupational candidate · not fully analyzed by the model</p><div class="why-box"><span>SOURCE-BASED ROLE FACTS</span><p>Skills and tasks are taken from the cited occupational profile. The matching rank is an editorial heuristic, not a validated measure of personal fit.</p></div><div class="path-columns"><div class="path-list"><span>MENTIONED SKILLS</span><ul>${(candidate.matched_skills??[]).map(x=>`<li>${e(x)}</li>`).join('')||'<li>No literal matches</li>'}</ul></div><div class="path-list"><span>NOT MENTIONED · VERIFY</span><ul>${(candidate.gaps??[]).slice(0,4).map(x=>`<li>${e(x)}</li>`).join('')||'<li>No unmentioned skills listed</li>'}</ul></div><div class="path-list"><span>NEXT EXPLORATION</span><p>Review one task from the cited role profile and build a small fictional work sample to test whether the work fits your goal.</p></div></div><div class="path-reality"><span>DATA LIMIT</span><p>This candidate has no model-generated fit explanation or four-week plan. Market outlook is United States O*NET data.</p><p>${e(candidate.growth)} · ${e(candidate.period)} · US</p>${references([candidate.source_id],s)}</div><button class="button ${pathId==='C'?'selected-button':'secondary'}" data-action="route-select:C">${pathId==='C'?'Current focus ✓':'Use this candidate'}</button></article>`:'';
  body=`<details class="explain-panel"><summary>How the matching score works</summary><p>0–70 points: mentioned skills / retrieved skills; 0–20: overlap of English input words with occupational tasks; 0–10: published growth category. This transparent heuristic is not a calibrated fit, hiring or replacement probability. Missing skill mentions are not proven weaknesses. Only five United States reference occupations are covered.</p></details><div class="ranking">${r.ranking.map((role,i)=>`<article><span>#${i+1}</span><div><strong>${e(role.title)}</strong><p>${e(role.growth)} · ${e(role.period)} · US</p><small>Skills ${role.components.skill_overlap}/70 · Context ${role.components.task_context}/20 · Trend ${role.components.published_trend}/10</small><details><summary>Skill overlap and gaps</summary><p>Matched: ${e(role.matched_skills.join(', ')||'No literal matches')}</p><p>Not mentioned: ${e(role.gaps.join(', '))}</p><p>Context words: ${e(role.overlap_terms.join(', ')||'None')}</p>${references([role.source_id],s)}<p>SDG ${e(role.sdg.target)}: ${e(role.sdg.rationale)}</p></details></div><b>${role.score}<small>/100</small></b></article>`).join('')}</div><h2 class="section-space">AI-analyzed routes</h2><div class="paths-grid">${a.paths.map(p=>`<article class="path-card ${pathId===p.kind?'selected':''}"><span class="kicker">PATH ${e(p.kind)}</span><h2>${p.kind==='A'?'Upgrade your current work':'Explore an adjacent career'}</h2><p>${e(r.ranking.find(x=>x.id===p.role_id).title)}${p.kind==='A'?' · reference role':''}</p>${claim(p.why,s)}${skillList('TRANSFERABLE STRENGTHS',p.transferable,s)}${skillList('SKILLS TO DEVELOP',p.gaps,s)}<strong>Practical challenge</strong>${claim(p.challenge,s)}<strong>Next experiment</strong>${claim(p.next_step,s)}${sdg(p.sdg)}<button class="button secondary" data-action="select:${p.kind}">${pathId===p.kind?'Selected ✓':'Focus on this path'}</button></article>`).join('')}</div>${candidate?`<h2 class="section-space">Additional source-based candidate</h2><div class="paths-grid">${candidateCard}</div>`:''}`;
 }
 if(page==='plan') {
  const p=a.paths.find(x=>x.kind===pathId);
  body=`<div class="plan-summary"><div><span>YOUR CHOICE · PATH ${e(p.kind)}</span><h2>${e(r.ranking.find(x=>x.id===p.role_id).title)}</h2><p>${e(r.profile.goal)}</p></div><div class="time-token"><strong>${r.weeklyHours}h</strong><span>weekly budget</span></div></div><p>Days 1–30 · ${(p.weeks.reduce((n,w)=>n+w.hours,0)).toFixed(1)} planned hours. Week 4 includes the final two review days; review is included in the budget.</p><section class="plan-mini"><span class="kicker">TOOLS TO EXPLORE</span>${p.tools.map(t=>`<h3>${e(s[t.resource_id].tool||s[t.resource_id].title)}</h3>${claim(t.purpose,s)}`).join('')}<p>Optional tools. Check access, pricing and workplace policy. Use fictional data only.</p></section><div class="week-list">${p.weeks.map(w=>`<article class="plan-mini"><span class="kicker">WEEK ${w.week} · DAYS ${1+(w.week-1)*7}–${w.week===4?30:w.week*7} · ${w.hours} HOURS TOTAL</span>${claim(w.action,s)}<p><strong>Deliver:</strong> ${e(w.deliverable)}</p><p><strong>Validate:</strong> ${e(w.validation)}</p><p>Learning resource: ${references([w.resource_id],s)}</p></article>`).join('')}</div><div class="proof-box"><strong>Day 30 · review and decide</strong>${claim(p.day30_review,s)}</div><div class="reality-panel"><strong>Your constraints</strong><p>${e(r.profile.constraints)}</p></div>`;
 }
 return head+body+`<div class="method-note"><div><strong>Uncertainties and limits</strong><ul>${[...a.uncertainties,...r.limitations].map(x=>`<li>${e(x)}</li>`).join('')}</ul><p>Source snapshot ${e(r.evidence.version)} · retrieved ${e(r.evidence.retrieved_at)}. Report ${e(r.report_id)}.</p><p>${e(r.evidence.attribution)} <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a>. SDG mapping is a proposed contribution, not measured impact.</p><p>Source links provide context. They do not certify the model's interpretation. A human should review every recommendation.</p></div></div>`;
}
function skillList(title,skills,sources) {return `<div class="path-list"><span>${title}</span>${skills.map(x=>`<div><strong>${e(x.skill)}</strong>${claim(x.advice,sources)}${sdg(x.sdg)}</div>`).join('')}</div>`;}

export function sourceRadar(snapshot) {
 return `<section class="source-radar"><span class="kicker">LIVE PUBLIC SOURCES</span><p>Retrieved ${e(snapshot.retrieved_at)} · snapshot ${e(snapshot.version)} · ${e(snapshot.geography)}</p>${snapshot.warnings.map(x=>`<p class="field-error">${e(x)}</p>`).join('')}<div class="task-grid">${snapshot.roles.map(r=>`<article class="task-card"><h3>${e(r.title)}</h3><p>${e(r.growth)}</p><small>Projection ${e(r.period)} · source updated ${e(r.updated)}</small><p><a href="${safeURL(r.url)}" target="_blank" rel="noopener noreferrer">O*NET occupational source ↗</a></p></article>`).join('')}</div><details class="plan-mini"><summary>AI research signals · not proven job-market effects</summary>${snapshot.research.map(x=>`<p><a href="${safeURL(x.url)}" target="_blank" rel="noopener noreferrer">${e(x.title)}</a><br><small>${e(x.date)} · preprint; human review required</small></p>`).join('')}</details></section>`;
}
